// fable2_keycap_swap.h
//
// Real-time swap of the controller prompt images between the original Xbox 360
// controller icons and the keyboard/mouse keycaps generated by the launcher.
//
// Background
// ----------
// The keyboard-prompt feature (see launcher/Fable2.Launcher/KeyboardPrompts.cs)
// used to rewrite the controller icon textures directly inside
// data/art/gui/gui_textures.bnk, which meant the player had to relaunch to get
// the keyboard/mouse images vs. the standard controller images.
//
// Instead of editing the bank on disk, the launcher now renders the keycap
// textures and writes them to a small sidecar file next to the bank
// (keyboard_prompts.bin, see kSidecarName). At startup this module reads the
// sidecar and the original bank bytes, installs the SDK post-read hook
// (RexSetXFilePostReadHook) so it can (a) serve the active variant whenever the
// bank is (re)read and (b) record the guest address the read landed in.
//
// Pressing the toggle key (default "L") flips the active variant and, for each
// already-loaded texture, writes the new pixel bytes straight into the guest
// buffer and drops the GPU's cached copy (Memory::InvalidateGpuCopies) so the
// next reference re-uploads the new pixels. The swap is visible in real time
// with no relaunch.
//
// Threading: the post-read hook fires from whichever guest thread performs the
// file read; PollToggle runs from host input polling. All shared state is
// guarded by a mutex.

#pragma once

#include <atomic>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <mutex>
#include <string>
#include <vector>

#include <rex/input/input_system.h>
#include <rex/runtime.h>
#include <rex/system/xfile.h>
#include <rex/system/xmemory.h>
#include <rex/ui/keybinds.h>
#include <rex/ui/virtual_key.h>

#ifdef _WIN32
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>
#endif

namespace fable2::keycap {

// Sidecar file name (relative to the game data root) written by the launcher.
inline constexpr const char* kSidecarName = "keyboard_prompts.bin";
// Little-endian magic for the sidecar: 'K','B','P','M'.
inline constexpr uint32_t kSidecarMagic = 0x4D50424Bu;
// Sidecar version 2 carries both the original (full-RGBA) and keyboard (keycap)
// payloads per entry, so the swap module does not need to read the bank for the
// original (the compressed icons are served from a rebuilt .keycap/ bank, and the
// original's decoded pixels are not in the on-disk bank).
inline constexpr uint32_t kSidecarVersion = 2;

// One affected bank entry (a controller icon texture).
struct Entry {
  std::string bank_path;  // Game-relative path, e.g. "data/art/gui/gui_textures.bnk".
  uint64_t abs_offset = 0;  // Absolute offset of the entry within the bank file.
  uint32_t size = 0;  // Entry length in bytes.
  std::vector<uint8_t> original;  // Original entry payload (from the bank file).
  std::vector<uint8_t> keyboard;  // Keyboard-variant entry payload (same size).
  // Recorded by the post-read hook: guest virtual address where this entry
  // was last read (diagnostic only; the live pixels are located by scan).
  uint32_t guest_address = 0;
  bool guest_address_valid = false;
  // Cache of where this texture's decoded pixels live in physical RAM, so a
  // repeated mode switch can verify + patch in place instead of rescanning all
  // 512 MB. Rebuilt by a scan whenever a cached buffer stops holding the
  // expected pixels (i.e. the texture was evicted and re-streamed elsewhere).
  uint32_t cached_addrs[4] = {0, 0, 0, 0};
  int cached_count = 0;
  int cached_order = 0;  // byte order (0 = identity, 1 = R<->B) at those buffers
};

// Lightweight diagnostic log (fable2_keycap_swap.log next to the exe). Lets us
// verify the sidecar loaded, the guest read buffer was recorded, and the
// toggle fired, without touching the game.
inline void Log(const std::string& msg) {
#ifdef _WIN32
  static std::FILE* f = [] {
    wchar_t exe_path[MAX_PATH];
    if (GetModuleFileNameW(nullptr, exe_path, MAX_PATH) > 0) {
      std::string dir = std::filesystem::path(exe_path).parent_path().string();
      if (std::FILE* out = std::fopen((dir + "/fable2_keycap_swap.log").c_str(), "ab"))
        return out;
    }
  }();
#else
  static std::FILE* f = std::fopen("fable2_keycap_swap.log", "ab");
#endif
  static std::mutex log_lock;
  if (!f) return;
  std::lock_guard lock(log_lock);
  std::fprintf(f, "%s\n", msg.c_str());
  std::fflush(f);
}

class KeycapSwap;
// Declared before the class so the inline FileReadTrampoline can call it
// (non-dependent names in an inline member body aren't looked up after the
// class body).
KeycapSwap& Instance();

class KeycapSwap {
 public:
  // Loads the sidecar and the original bank bytes, then installs the SDK
  // post-read hook. No-op (stays disabled) if the sidecar is missing or
  // invalid, so a normal (non-keyboard-prompt) launch is unaffected.
  void Init(rex::memory::Memory* memory, const std::filesystem::path& game_data_root) {
    std::lock_guard lock(mutex_);
    memory_ = memory;
    if (memory_ == nullptr || !LoadSidecar(game_data_root)) {
      enabled_ = false;
      Log("Init: disabled (no valid " + std::string(kSidecarName) + ")");
      return;
    }
    enabled_ = true;
    Log("Init: enabled, " + std::to_string(entries_.size()) +
        " entries (prompt variant follows the active input device)");
    for (size_t i = 0; i < entries_.size(); ++i) {
      Log("  [" + std::to_string(i) + "] " + entries_[i].bank_path + " offset="
          + HexAddr(static_cast<uint32_t>(entries_[i].abs_offset)) +
          " size=" + std::to_string(entries_[i].size));
    }
    // Install the hook (a no-op if the feature is disabled, but harmless).
    rex::system::RexSetXFilePostReadHook(&KeycapSwap::FileReadTrampoline);
  }

  // Call once per frame (from the keyboard-gamepad driver). Sets the prompt
  // variant to match guest user 0's most recent input device: a synthetic
  // keyboard/mouse device -> keycap icons, a physical pad (or no input yet) ->
  // controller icons. Re-patches the live textures only when the mode changes.
  void UpdateFromActiveDevice() {
    if (!enabled_) return;
    const int target = ActiveDeviceIsKeyboard() ? 1 : 0;
    std::lock_guard lock(mutex_);
    if (!memory_ || target == mode_) return;
    const int old = mode_;
    mode_ = target;
    ApplyModeChange(old, target);
  }

  // True if guest user 0's most recent non-neutral input came from a synthetic
  // (keyboard/mouse) device. The SDK tracks this in the input system every
  // frame (ActiveDeviceTracker), updated inside InputSystem::GetState.
  static bool ActiveDeviceIsKeyboard() {
    auto* rt = rex::Runtime::instance();
    if (!rt) return false;
    auto* sys = static_cast<rex::input::InputSystem*>(rt->input_system());
    if (!sys) return false;
    return sys->ActiveDeviceIsSynthetic(0);  // guest user 0
  }

  bool enabled() const { return enabled_; }
  bool keyboard_mode() const { return mode_ != 0; }

 private:
  // Free-function trampoline so the C hook can reach the singleton.
  static void FileReadTrampoline(const char* path, uint8_t* host_buffer, size_t bytes_read,
                                 uint64_t byte_offset, uint32_t guest_address) {
    Instance().OnFileRead(path, host_buffer, bytes_read, byte_offset, guest_address);
  }

  bool LoadSidecar(const std::filesystem::path& game_data_root) {
    const std::filesystem::path sidecar = game_data_root / kSidecarName;
    std::vector<uint8_t> raw;
    {
      std::FILE* f = std::fopen(sidecar.string().c_str(), "rb");
      if (!f) return false;
      std::fseek(f, 0, SEEK_END);
      long len = std::ftell(f);
      std::fseek(f, 0, SEEK_SET);
      if (len <= 0) {
        std::fclose(f);
        return false;
      }
      raw.resize(size_t(len));
      size_t got = std::fread(raw.data(), 1, size_t(len), f);
      std::fclose(f);
      if (got != size_t(len)) return false;
    }
    if (raw.size() < 12) return false;
    auto rd_u32 = [&](size_t& off) -> uint32_t {
      uint32_t v;
      std::memcpy(&v, raw.data() + off, 4);
      off += 4;
      return v;
    };
    size_t off = 0;
    if (rd_u32(off) != kSidecarMagic) return false;
    if (rd_u32(off) != kSidecarVersion) return false;
    uint32_t entry_count = rd_u32(off);
    if (entry_count == 0) return false;

    entries_.clear();
    for (uint32_t i = 0; i < entry_count; ++i) {
      uint32_t name_len = rd_u32(off);
      if (off + name_len + 12 > raw.size()) return false;
      std::string bank_path(reinterpret_cast<const char*>(raw.data() + off), name_len);
      off += name_len;
      uint64_t abs_offset;
      std::memcpy(&abs_offset, raw.data() + off, 8);
      off += 8;
      uint32_t size = rd_u32(off);
      if (off + 2u * size > raw.size()) return false;
      Entry e;
      e.bank_path = bank_path;
      e.abs_offset = abs_offset;
      e.size = size;
      e.original.assign(raw.begin() + off, raw.begin() + off + size);
      off += size;
      e.keyboard.assign(raw.begin() + off, raw.begin() + off + size);
      off += size;
      entries_.push_back(std::move(e));
    }
    return true;
  }

  static bool ReadBankRange(const std::filesystem::path& path, uint64_t offset, uint32_t size,
                            std::vector<uint8_t>& out) {
    std::FILE* f = std::fopen(path.string().c_str(), "rb");
    if (!f) return false;
    bool ok = std::fseek(f, long(offset), SEEK_SET) == 0;
    if (ok) {
      out.resize(size);
      ok = size == 0 || std::fread(out.data(), 1, size, f) == size;
    }
    std::fclose(f);
    return ok;
  }

  // Case-insensitive substring match of the bank's final component(s) against
  // the VFS read path (which may use either slash direction).
  static bool BankMatches(const std::string& bank_path, const char* vfs_path) {
    if (bank_path.empty() || vfs_path == nullptr) return false;
    auto lower = [](std::string s) {
      for (char& c : s) c = char(tolower(uint8_t(c)));
      return s;
    };
    std::string target = lower(bank_path);
    for (char& c : target) if (c == '\\') c = '/';
    std::string hay = lower(vfs_path);
    for (char& c : hay) if (c == '\\') c = '/';
    // Use the bank's tail (strip a leading "data/" or "game:" style prefix).
    auto find_tail = [](const std::string& s) -> std::string {
      // Take from the first "data/" if present, else the whole string.
      size_t d = s.find("data/");
      return d != std::string::npos ? s.substr(d) : s;
    };
    std::string needle = find_tail(target);
    return hay.find(needle) != std::string::npos;
  }

  void OnFileRead(const char* path, uint8_t* host_buffer, size_t bytes_read, uint64_t byte_offset,
                  uint32_t guest_address) {
    if (!enabled_) return;
    std::lock_guard lock(mutex_);
    const uint64_t read_start = byte_offset;
    const uint64_t read_end = byte_offset + bytes_read;
    for (auto& entry : entries_) {
      if (!BankMatches(entry.bank_path, path)) continue;
      const uint64_t entry_start = entry.abs_offset;
      const uint64_t entry_end = entry.abs_offset + entry.size;
      if (entry_end <= read_start || entry_start >= read_end) continue;  // no overlap
      const uint64_t ov_start = std::max(entry_start, read_start);
      const uint64_t ov_len = std::min(entry_end, read_end) - ov_start;
      const uint8_t* src = (mode_ != 0) ? entry.keyboard.data() : entry.original.data();
      std::memcpy(host_buffer + (ov_start - read_start), src + (ov_start - entry_start), ov_len);
      if (byte_offset <= entry_start) {
        entry.guest_address = guest_address + uint32_t(entry_start - byte_offset);
        if (!entry.guest_address_valid) {
          Log("OnFileRead: recorded guest address " + HexAddr(entry.guest_address) +
              " for " + entry.bank_path + " offset=0x" + HexAddr(static_cast<uint32_t>(entry.abs_offset)) +
              " (vfs: " + (path ? path : "?") + ")");
        }
        entry.guest_address_valid = true;
      }
    }
  }

  // Scans the pre-committed 512MB guest main memory (physical RAM) for full matches
  // of `needle`, recording guest addresses of the form 0xA0000000 + phys_offset (the
  // vA0000000 physical view, so LookupHeap routes them to the physical heap and the
  // GPU page-keyed texture cache). Returns the number of matches (up to cap).
  int FindMatchesInPhysical(const uint8_t* needle, size_t nlen, uint32_t* out, int cap) {
    int count = 0;
    if (nlen == 0) return 0;
    uint8_t* base = memory_->physical_membase();
    const uint64_t total = 0x20000000ull;  // 512MB guest RAM
    size_t k = 0;
    while (k < nlen && needle[k] == 0) k++;
    if (k >= nlen) return 0;  // all-zero needle: nothing to match
    const uint8_t key = needle[k];
    const uint8_t* limit_start = base + (total - nlen);
    const uint8_t* q = base;
    while (q <= limit_start) {
      const uint8_t* hit = static_cast<const uint8_t*>(std::memchr(q, key, limit_start + 1 - q));
      if (!hit) break;
      const uint8_t* cand = hit - k;
      if (cand >= base && std::memcmp(cand, needle, nlen) == 0) {
        const uint64_t off = static_cast<uint64_t>(cand - base);
        if (count < cap) out[count] = 0xA0000000u + static_cast<uint32_t>(off);
        count++;
        q = cand + nlen;
      } else {
        q = hit + 1;
      }
    }
    return count;
  }

  // Copies `px` into `out`, optionally swapping the R and B bytes of every pixel
  // (order 1) to cover RGBA vs. BGR(A) storage of the decoded texture.
  static void BuildPixels(const uint8_t* px, size_t len, int order, std::vector<uint8_t>& out) {
    out.resize(len);
    if (order == 0) {
      std::memcpy(out.data(), px, len);
    } else {
      for (size_t i = 0; i + 4 <= len; i += 4) {
        out[i + 0] = px[i + 2];
        out[i + 1] = px[i + 1];
        out[i + 2] = px[i + 0];
        out[i + 3] = px[i + 3];
      }
      for (size_t i = len - (len % 4); i < len; ++i) out[i] = px[i];
    }
  }

  // Writes `nxt` pixels (in the given byte order) into the buffer at the given
  // physical-view guest address and drops its GPU copy so it re-uploads.
  void PatchBuffer(Entry& e, uint32_t guest_addr, int order, const uint8_t* nxt, size_t px_len) {
    uint8_t* live = memory_->physical_membase() + (static_cast<uint64_t>(guest_addr) - 0xA0000000ull);
    std::vector<uint8_t> rep;
    BuildPixels(nxt, px_len, order, rep);
    std::memcpy(live, rep.data(), px_len);
    memory_->InvalidateGpuCopies(guest_addr, static_cast<uint32_t>(px_len));
  }

  // Caller must hold mutex_. Rewrites each live texture in physical RAM from
  // old_mode's pixels to new_mode's pixels and drops the GPU copy so it
  // re-uploads. mode_ is set by the caller before this runs.
  void ApplyModeChange(int old_mode, int new_mode) {
    Log(std::string("Keycap mode: ") + (old_mode == 0 ? "controller" : "keyboard") + " -> " +
        (new_mode == 0 ? "controller" : "keyboard"));
    int patched_total = 0;
    for (size_t i = 0; i < entries_.size(); ++i) {
      auto& e = entries_[i];
      if (e.size <= 4) continue;
      const size_t px_len = e.size - 4;  // skip the 4-byte pixel_byte_count prefix
      const uint8_t* cur = (old_mode != 0) ? e.keyboard.data() + 4 : e.original.data() + 4;
      const uint8_t* nxt = (new_mode != 0) ? e.keyboard.data() + 4 : e.original.data() + 4;

      // Fast path: if every cached buffer still holds the current pixels (in
      // the cached byte order), patch them in place and skip the 512 MB scan.
      // This is the common case when swapping input devices within a menu, so
      // it removes the per-switch memory-scan lag spike.
      if (e.cached_count > 0) {
        std::vector<uint8_t> cur_px;
        BuildPixels(cur, px_len, e.cached_order, cur_px);
        bool all_valid = true;
        for (int j = 0; j < e.cached_count; ++j) {
          uint8_t* p = memory_->physical_membase() + (e.cached_addrs[j] - 0xA0000000ull);
          if (std::memcmp(p, cur_px.data(), px_len) != 0) { all_valid = false; break; }
        }
        if (all_valid) {
          for (int j = 0; j < e.cached_count; ++j) {
            PatchBuffer(e, e.cached_addrs[j], e.cached_order, nxt, px_len);
            patched_total++;
          }
          Log("  entry[" + std::to_string(i) + "] cache hit: patched " +
              std::to_string(e.cached_count) + " buffer(s)");
          continue;
        }
      }

      // Slow path: scan physical RAM for the current pixels, patch every copy,
      // and (re)build the cache so the next switch takes the fast path.
      int found = 0;
      uint32_t addrs[4];
      for (int order = 0; order < 2 && found == 0; ++order) {
        std::vector<uint8_t> needle;
        BuildPixels(cur, px_len, order, needle);
        found = FindMatchesInPhysical(needle.data(), needle.size(), addrs, 4);
        if (found > 0) {
          for (int j = 0; j < found && j < 4; ++j) {
            const uint64_t phys_off = static_cast<uint64_t>(addrs[j]) - 0xA0000000ull;
            uint8_t* live = memory_->physical_membase() + phys_off;
            if (j == 0) {
              Log("  entry[" + std::to_string(i) + "] live=" + HexDump(live, 16) +
                  " expected=" + HexDump(cur, 16) +
                  (std::memcmp(live, needle.data(), 16) == 0 ? " match=yes" : " match=NO") +
                  " (scanned)");
            }
            PatchBuffer(e, addrs[j], order, nxt, px_len);
            patched_total++;
            if (j == 0) Log("    -> patched @" + HexAddr(addrs[j]) + " order=" +
                            std::to_string(order) + " (found " + std::to_string(found) + " copies)");
          }
          // Rebuild the cache from this scan.
          e.cached_count = found > 4 ? 4 : found;
          for (int j = 0; j < e.cached_count; ++j) e.cached_addrs[j] = addrs[j];
          e.cached_order = order;
        }
      }
      if (found == 0) {
        e.cached_count = 0;
        Log("  entry[" + std::to_string(i) + "] NOT FOUND in physical RAM (first16=" +
            HexDump(cur, 16) + ")");
      }
    }
    Log("Keycap mode done: patched " + std::to_string(patched_total) + " buffer(s)");
  }

  static std::string HexAddr(uint32_t a) {
    char buf[12];
    std::snprintf(buf, sizeof(buf), "0x%08X", a);
    return buf;
  }

  static std::string HexDump(const uint8_t* p, size_t n) {
    static const char* hex = "0123456789abcdef";
    std::string s;
    s.reserve(n * 3);
    for (size_t i = 0; i < n; ++i) {
      s.push_back(hex[p[i] >> 4]);
      s.push_back(hex[p[i] & 0xF]);
      s.push_back(' ');
    }
    return s;
  }

  std::mutex mutex_;
  rex::memory::Memory* memory_ = nullptr;
  std::vector<Entry> entries_;
  bool enabled_ = false;
  int mode_ = 0;  // 0 = controller (Xbox 360), 1 = keyboard/mouse.
};

inline KeycapSwap& Instance() {
  static KeycapSwap instance;
  return instance;
}

}  // namespace fable2::keycap
